#!/usr/bin/env node
/**
 * Velmont — One-time brand asset generator (favicons + default OG image).
 *
 * Source: public/assets/logos/velmont-main.png (full wordmark, 20001x10001).
 * Re-run manually if the source logo changes; output is committed, not
 * regenerated by `npm run build`.
 *
 * Usage: node scripts/generate-brand-assets.js
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const LOGO = path.join(ROOT, 'public', 'assets', 'logos', 'velmont-main.png');
const PUBLIC = path.join(ROOT, 'public');
const OG_DIR = path.join(PUBLIC, 'assets', 'og');

const PAPER = '#f4f0eb';
const TERRACOTTA = '#ff4015';

// Tight crop around the terracotta "M" chair-mark at the center of the
// wordmark (found by visual inspection of the 20001x10001 source).
const MARK_CROP = { left: 8300, top: 3400, width: 3600, height: 3300 };

async function markBuffer() {
  const cropped = await sharp(LOGO).extract(MARK_CROP).toBuffer();
  return sharp(cropped).trim({ threshold: 10 }).toBuffer();
}

async function squareIcon(mark, size, fill) {
  const inner = Math.round(size * 0.62);
  const resizedMark = await sharp(mark)
    .resize({ width: inner, height: inner, fit: 'inside' })
    .toBuffer();
  const markMeta = await sharp(resizedMark).metadata();
  return sharp({
    create: { width: size, height: size, channels: 4, background: fill },
  })
    .composite([
      {
        input: resizedMark,
        left: Math.round((size - markMeta.width) / 2),
        top: Math.round((size - markMeta.height) / 2),
      },
    ])
    .png()
    .toBuffer();
}

async function buildFavicons(mark) {
  const favicon32 = await squareIcon(mark, 32, PAPER);
  const favicon16 = await squareIcon(mark, 16, PAPER);
  const appleTouchIcon = await squareIcon(mark, 180, PAPER);
  await fs.writeFile(path.join(PUBLIC, 'favicon-32.png'), favicon32);
  await fs.writeFile(path.join(PUBLIC, 'favicon-16.png'), favicon16);
  await fs.writeFile(path.join(PUBLIC, 'apple-touch-icon.png'), appleTouchIcon);
  console.log('[generate-brand-assets] wrote favicon-32.png, favicon-16.png, apple-touch-icon.png');
}

async function buildDefaultOg() {
  const W = 1200;
  const H = 630;
  const logo = await sharp(LOGO).resize({ width: 640 }).toBuffer();
  const logoMeta = await sharp(logo).metadata();
  const ruleWidth = 120;
  const ruleY = Math.round(H / 2 + logoMeta.height / 2 + 48);

  const rule = await sharp({
    create: {
      width: ruleWidth,
      height: 4,
      channels: 4,
      background: TERRACOTTA,
    },
  })
    .png()
    .toBuffer();

  await fs.mkdir(OG_DIR, { recursive: true });
  await sharp({
    create: { width: W, height: H, channels: 4, background: PAPER },
  })
    .composite([
      {
        input: logo,
        left: Math.round((W - logoMeta.width) / 2),
        top: Math.round((H - logoMeta.height) / 2) - 20,
      },
      {
        input: rule,
        left: Math.round((W - ruleWidth) / 2),
        top: ruleY,
      },
    ])
    .jpeg({ quality: 90 })
    .toFile(path.join(OG_DIR, 'default-og.jpg'));
  console.log('[generate-brand-assets] wrote assets/og/default-og.jpg');
}

async function main() {
  const mark = await markBuffer();
  await buildFavicons(mark);
  await buildDefaultOg();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
